package br.com.luvi.financaspessoais.lancamento.entity;
import br.com.luvi.financaspessoais.conta.entity.ContaFinanceira; import br.com.luvi.financaspessoais.categoria.entity.Categoria; import br.com.luvi.financaspessoais.usuario.entity.Usuario; import br.com.luvi.financaspessoais.lancamento.enums.*; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="lancamentos") public class Lancamento { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private TipoLancamento tipo; @Column(nullable=false,length=200) private String descricao; @ManyToOne(optional=false) @JoinColumn(name="categoria_id",nullable=false) private Categoria categoria; @Column(nullable=false,precision=12,scale=2) private BigDecimal valor; @Column(nullable=false) private LocalDate data; @Column(name="data_hora_cadastro") private LocalDateTime dataHoraCadastro; @ManyToOne @JoinColumn(name="conta_id") private ContaFinanceira conta; @ManyToOne @JoinColumn(name="usuario_criacao_id") private Usuario usuarioCriacao; @PrePersist public void pre(){if(dataHoraCadastro==null)dataHoraCadastro=LocalDateTime.now();} public Long getId(){return id;} public TipoLancamento getTipo(){return tipo;} public void setTipo(TipoLancamento v){tipo=v;} public String getDescricao(){return descricao;} public void setDescricao(String v){descricao=v;} public Categoria getCategoria(){return categoria;} public void setCategoria(Categoria v){categoria=v;} public BigDecimal getValor(){return valor;} public void setValor(BigDecimal v){valor=v;} public LocalDate getData(){return data;} public void setData(LocalDate v){data=v;} public LocalDateTime getDataHoraCadastro(){return dataHoraCadastro;} public ContaFinanceira getConta(){return conta;} public void setConta(ContaFinanceira v){conta=v;} public Usuario getUsuarioCriacao(){return usuarioCriacao;} public void setUsuarioCriacao(Usuario v){usuarioCriacao=v;} }